    'last_citation_observed_at',
    'audit_match_state',
    'audit_url',
    'audit_timestamp',
    'date_modified_alignment_state',
    'schema_date_modified_days',
    'latest_schema_date_modified_day',
    'days_from_last_citation_observation_to_schema_date_modified',
