function parseCsvRows(text: string): string[][] {
  const decodeCell = (value: string): string => value.replace(/^(\s*)'(?=[=+\-@])/, '$1');
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index]!;
    if (character === '"') {
      if (quoted && text[index + 1] === '"') {
        field += '"';
        index += 1;
      } else {
        quoted = !quoted;
      }
    } else if (!quoted && character === ',') {
      row.push(decodeCell(field));
      field = '';
    } else if (!quoted && (character === '\n' || character === '\r')) {
      row.push(decodeCell(field));
      rows.push(row);
      row = [];
      field = '';
      if (character === '\r' && text[index + 1] === '\n') index += 1;
    } else {
      field += character;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(decodeCell(field));
    rows.push(row);
  }
  return rows;
}

export interface AiAnswerCitationPromptPlanTargetSummary {
  providerCohortQuotasBelowTarget: number;
  cohortsBelowPromptOverlapTarget: number;
  providerCohortPrecisionMarginsAboveTarget: number;
  cohortRowsAnalyzed: number;
  requiredPairedPromptGroups: number;
  plannedPairedPromptGroups: number;
  deferredPairedPromptGroups: number;
  requiredPairedProviderCaptureRuns: number;
  plannedPairedProviderCaptureRuns: number;
  providerSpecificAdditionalPromptQuotas: number;
  providerPairBudgets: AiAnswerCitationPromptPlanProviderPairBudget[];
  detailsCapped: boolean;
  outputRowsTruncated: boolean;
  targetsMet: boolean;
}

export interface AiAnswerCitationPromptPlanProviderPairBudget {
  providerA: string;
  providerB: string;
  requiredPairedPromptGroups: number;
  plannedPairedPromptGroups: number;
  deferredPairedPromptGroups: number;
  allocation: AiAnswerCitationPromptPlanTotalPairAllocation | 'not_applicable';
}

function summarizeAiAnswerCitationPromptPlanRows(
  report: AiAnswerCitationObservationReport,
  parsed: string[][],
  ownedPromptReachTargetHalfWidthPercentagePoints?: number
): AiAnswerCitationPromptPlanTargetSummary {
  const headers = parsed[0] ?? [];
  const rows = parsed.slice(1);
  const column = (name: string): number => headers.indexOf(name);
  const read = (row: string[], name: string): string => {
    const index = column(name);
    return index < 0 ? '' : (row[index] ?? '');
  };
  let providerCohortQuotasBelowTarget = 0;
  let providerCohortPrecisionMarginsAboveTarget = 0;
  let detailsCapped = false;
  let outputRowsTruncated = false;
  let providerSpecificAdditionalPromptQuotas = 0;
  const cohortsBelowPromptOverlapTarget = new Set<string>();
  const pairedGroupCounts = new Map<
    string,
    { required: number; planned: number; deferred: number }
  >();
  const pairBudgetCounts = new Map<string, AiAnswerCitationPromptPlanProviderPairBudget>();
  for (const row of rows) {
    if (read(row, 'cohort_prompt_quota_met_after_budget') !== 'true')
      providerCohortQuotasBelowTarget += 1;
    if (read(row, 'prompt_overlap_target_met_after_budget') === 'false') {
      cohortsBelowPromptOverlapTarget.add(
        `${read(row, 'provider_a')}\u0000${read(row, 'provider_b')}\u0000${read(row, 'topic')}\u0000${read(row, 'intent')}`
      );
    }
    if (ownedPromptReachTargetHalfWidthPercentagePoints !== undefined) {
      const afterBudgetValue = read(
        row,
        'owned_prompt_reach_worst_case_95_wilson_half_width_after_budget_percentage_points'
      );
      const afterBudget = Number(afterBudgetValue);
      if (
        afterBudgetValue === '' ||
        !Number.isFinite(afterBudget) ||
        afterBudget > ownedPromptReachTargetHalfWidthPercentagePoints + 0.00005
      ) {
        providerCohortPrecisionMarginsAboveTarget += 1;
      }
    }
    detailsCapped ||=
      read(row, 'topic_intent_cohort_catalog_truncated') === 'true' ||
      read(row, 'provider_pair_list_truncated') === 'true';
    outputRowsTruncated ||= read(row, 'output_rows_truncated') === 'true';
    providerSpecificAdditionalPromptQuotas += Number(
      read(row, 'suggested_additional_unique_prompts') || 0
    );
    const groupKey = JSON.stringify([
      read(row, 'provider_a'),
      read(row, 'provider_b'),
      read(row, 'topic'),
      read(row, 'intent'),
    ]);
    if (!pairedGroupCounts.has(groupKey)) {
      const providerA = read(row, 'provider_a');
      const providerB = read(row, 'provider_b');
      const pairKey = JSON.stringify([providerA, providerB]);
      const required = Number(read(row, 'minimum_paired_follow_up_groups_required') || 0);
      const planned = Number(read(row, 'paired_follow_up_prompt_groups_to_collect') || 0);
      const deferred = Number(read(row, 'paired_follow_up_groups_deferred_by_budget') || 0);
      pairedGroupCounts.set(groupKey, {
        required,
        planned,
        deferred,
      });
      const pairBudget = pairBudgetCounts.get(pairKey) ?? {
        providerA,
        providerB,
        requiredPairedPromptGroups: 0,
        plannedPairedPromptGroups: 0,
        deferredPairedPromptGroups: 0,
        allocation: (read(row, 'total_pair_budget_allocation') ||
          'not_applicable') as AiAnswerCitationPromptPlanProviderPairBudget['allocation'],
      };
      pairBudget.requiredPairedPromptGroups += required;
      pairBudget.plannedPairedPromptGroups += planned;
      pairBudget.deferredPairedPromptGroups += deferred;
      pairBudgetCounts.set(pairKey, pairBudget);
    }
  }
  detailsCapped ||=
    report.topicIntentCohortsTruncated === true ||
    report.providerSampleMixComparisonsTruncated === true;
  const overlapMisses = cohortsBelowPromptOverlapTarget.size;
  const requiredPairedPromptGroups = [...pairedGroupCounts.values()].reduce(
    (sum, counts) => sum + counts.required,
    0
  );
  const plannedPairedPromptGroups = [...pairedGroupCounts.values()].reduce(
    (sum, counts) => sum + counts.planned,
    0
  );
  const deferredPairedPromptGroups = [...pairedGroupCounts.values()].reduce(
    (sum, counts) => sum + counts.deferred,
    0
  );
  const targetsMet =
    rows.length > 0 &&
    !detailsCapped &&
    !outputRowsTruncated &&
    providerCohortQuotasBelowTarget === 0 &&
    overlapMisses === 0 &&
    providerCohortPrecisionMarginsAboveTarget === 0;
  return {
    providerCohortQuotasBelowTarget,
    cohortsBelowPromptOverlapTarget: overlapMisses,
    providerCohortPrecisionMarginsAboveTarget,
    cohortRowsAnalyzed: rows.length,
    requiredPairedPromptGroups,
    plannedPairedPromptGroups,
    deferredPairedPromptGroups,
    requiredPairedProviderCaptureRuns: requiredPairedPromptGroups * 2,
    plannedPairedProviderCaptureRuns: plannedPairedPromptGroups * 2,
    providerSpecificAdditionalPromptQuotas,
    providerPairBudgets: [...pairBudgetCounts.values()].sort(
      (left, right) =>
        left.providerA.localeCompare(right.providerA) ||
        left.providerB.localeCompare(right.providerB)
    ),
    detailsCapped,
    outputRowsTruncated,
    targetsMet,
  };
}

/** Summarize whether a bounded follow-up plan satisfies its requested quotas and precision targets. */
export function summarizeAiAnswerCitationPromptPlanTargets(
  report: AiAnswerCitationObservationReport,
  minimumPromptsPerProviderCohort = 0,
  ownedPromptReachTargetHalfWidthPercentagePoints?: number,
  minimumPromptSetJaccard?: number,
  maximumPairedFollowUpGroupsPerPair?: number,
  cohortTargets: AiAnswerCitationPromptPlanCohortTarget[] = [],
  maximumTotalPairedFollowUpGroups?: number,
  totalPairBudgetAllocation: AiAnswerCitationPromptPlanTotalPairAllocation = 'balanced'
): AiAnswerCitationPromptPlanTargetSummary {
  const parsed = parseCsvRows(
    renderAiAnswerCitationPromptSamplingPlanCsv(
      report,
      minimumPromptsPerProviderCohort,
      ownedPromptReachTargetHalfWidthPercentagePoints,
      minimumPromptSetJaccard,
      maximumPairedFollowUpGroupsPerPair,
      cohortTargets,
      maximumTotalPairedFollowUpGroups,
      totalPairBudgetAllocation
    )
  );
  return summarizeAiAnswerCitationPromptPlanRows(
    report,
    parsed,
    ownedPromptReachTargetHalfWidthPercentagePoints
  );
}

/** Export owned citation-event distribution by captured source-list rank. */
export function renderAiAnswerCitationOwnedRankCsv(
  report: AiAnswerCitationObservationReport
): string {
  const ranges: AiAnswerCitationListPositionProfile['positionBuckets'][number]['range'][] = [
    '1',
    '2',
    '3',
    '4-5',
    '6-10',
    '11+',
  ];
  const overall = report.summary.ownedCitationPositionBuckets;
  if (!overall || report.ownedDomains.length === 0) {
    throw new Error(
      'Owned citation rank export requires an answer-citation report analyzed with at least one owned domain.'
    );
  }
  const headers = [
    'scope',
    'provider',
    'rank_bucket',
    'owned_citation_events',
    'share_of_owned_citation_events_percent',
    'all_citation_events_at_rank',
    'owned_share_within_rank_percent',
    'first_owned_citation_mean_reciprocal_rank_percent',
  ];
  const toRows = (
    scope: string,
    provider: string,
    buckets: NonNullable<typeof overall>,
    meanReciprocalRank?: number | null
  ) =>
    ranges.map((range) => {
      const bucket = buckets.find((item) => item.range === range);
      return [
        scope,
        provider,
        range,
        bucket?.ownedCitationEvents,
        bucket?.ownedCitationEventSharePercent,
        bucket?.citationEvents,
        bucket?.ownedShareWithinPositionPercent,
        meanReciprocalRank,
      ];
    });
  const providerRows = report.providers.flatMap((provider) =>
    provider.ownedCitationPositionBuckets
      ? toRows(
          'provider',
          provider.provider,
          provider.ownedCitationPositionBuckets,
          provider.ownedFirstCitationMeanReciprocalRankPercent
        )
      : []
  );
  return `${[headers, ...toRows('all-providers', '', overall, report.summary.ownedFirstCitationMeanReciprocalRankPercent), ...providerRows].map((row) => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

