/** Summarize whether operator-recorded model, surface, and locale labels cover the sampled answers. */
export function renderAiAnswerCitationExecutionContextCoverageCsv(
  report: AiAnswerCitationObservationReport
): string {
  const overallProfiles = report.executionContextProfiles;
  if (!overallProfiles)
    throw new Error(
      'Execution-context coverage requires answer observations with at least one model, surface, or locale label.'
    );

  interface CoverageAccumulator {
    provider: string;
    month?: string;
    topic?: string;
    intent?: string;
    topicIntentLabeled: boolean;
    observations: number;
    modelObservations: number;
    surfaceObservations: number;
    localeObservations: number;
    allDimensionsObservations: number;
    models: Set<string>;
    surfaces: Set<string>;
    locales: Set<string>;
  }
  const headers = [
    'period',
    'month_utc',
    'provider',
    'topic',
    'intent',
    'topic_intent_labeled',
    'observations',
    'observations_with_model',
    'model_label_coverage_percent',
    'distinct_model_labels',
    'observations_with_surface',
    'surface_label_coverage_percent',
    'distinct_surface_labels',
    'observations_with_locale',
    'locale_label_coverage_percent',
    'distinct_locale_labels',
    'observations_with_model_surface_locale',
    'all_three_label_coverage_percent',
    'context_profile_detail_complete',
  ];
  const outputRows: unknown[][] = [];

  const appendProfiles = (
    profiles: Array<AiAnswerCitationExecutionContextProfile & { month?: string }>,
    period: 'all-sampled' | 'month',
    detailComplete: boolean
  ): void => {
    const groups = new Map<string, CoverageAccumulator>();
    for (const profile of profiles) {
      const month = period === 'month' ? profile.month : undefined;
      const key = JSON.stringify([
        month ?? null,
        profile.provider,
        profile.topic ?? null,
        profile.intent ?? null,
        profile.unlabeledTopicIntent,
      ]);
      const group = groups.get(key) ?? {
        provider: profile.provider,
        ...(month ? { month } : {}),
        ...(profile.topic ? { topic: profile.topic } : {}),
        ...(profile.intent ? { intent: profile.intent } : {}),
        topicIntentLabeled: !profile.unlabeledTopicIntent,
        observations: 0,
        modelObservations: 0,
        surfaceObservations: 0,
        localeObservations: 0,
        allDimensionsObservations: 0,
        models: new Set<string>(),
        surfaces: new Set<string>(),
        locales: new Set<string>(),
      };
      group.observations += profile.observations;
      if (profile.model !== undefined) {
        group.modelObservations += profile.observations;
        group.models.add(profile.model);
      }
      if (profile.surface !== undefined) {
        group.surfaceObservations += profile.observations;
        group.surfaces.add(profile.surface);
      }
      if (profile.locale !== undefined) {
        group.localeObservations += profile.observations;
        group.locales.add(profile.locale);
      }
      if (
        profile.model !== undefined &&
        profile.surface !== undefined &&
        profile.locale !== undefined
      ) {
        group.allDimensionsObservations += profile.observations;
      }
      groups.set(key, group);
    }

    const ordered = [...groups.values()].sort(
      (left, right) =>
        left.provider.localeCompare(right.provider) ||
        (left.month ?? '').localeCompare(right.month ?? '') ||
        (left.topic ?? '').localeCompare(right.topic ?? '') ||
        (left.intent ?? '').localeCompare(right.intent ?? '')
    );
    for (const group of ordered) {
      const coverage = (count: number): number | undefined =>
        group.observations > 0
          ? Number(((count / group.observations) * 100).toFixed(2))
          : undefined;
      outputRows.push([
        period,
        group.month,
        group.provider,
        group.topic,
        group.intent,
        group.topicIntentLabeled,
        group.observations,
        group.modelObservations,
        coverage(group.modelObservations),
        group.models.size,
        group.surfaceObservations,
        coverage(group.surfaceObservations),
        group.surfaces.size,
        group.localeObservations,
        coverage(group.localeObservations),
        group.locales.size,
        group.allDimensionsObservations,
        coverage(group.allDimensionsObservations),
        detailComplete,
      ]);
    }
  };

  appendProfiles(overallProfiles, 'all-sampled', !report.executionContextProfilesTruncated);
  if (report.executionContextMonthlyProfiles) {
    appendProfiles(
      report.executionContextMonthlyProfiles,
      'month',
      !report.executionContextMonthlyProfilesTruncated
    );
  }
  return `${[headers, ...outputRows].map((row) => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

