/** Export exact-prompt citation-domain retention to the next distinct sampled timestamp. */
export function renderAiAnswerCitationSourcePersistenceCsv(
  report: AiAnswerCitationObservationReport
): string {
  const profiles = report.sourcePersistenceProfiles;
  if (!profiles)
    throw new Error(
      'This report does not contain source-persistence detail; reanalyze the source observations.'
    );
  const note =
    'Within each provider, exact normalized prompt, and recorded context group, captures sharing one timestamp are combined as present when any capture cites the domain. Retention is calculated only over transitions whose next timestamp is observable; when the source is absent and every simultaneous citation list is incomplete, the transition is unknown and excluded from retention denominators. Set citationListComplete=false for incomplete observations; a 50-URL list defaults to incomplete unless explicitly marked true. First appearance after prior absence is counted only when a previous list confirms absence; prior-state unknown counts are exported separately. Follow-up bands show elapsed time, equal-prompt means use deterministic prompt-cluster bootstrap intervals when supported, and previous-rank bands use the best observed source-list position at the prior timestamp. This describes sampled transitions, not continuous-time survival or source quality.';
  const intervalColumns = [
    { key: '0_1_days', index: 0 },
    { key: 'over_1_7_days', index: 1 },
    { key: 'over_7_30_days', index: 2 },
    { key: 'over_30_90_days', index: 3 },
    { key: 'over_90_days', index: 4 },
  ];
  const rankColumns = [
    { key: 'rank_1', index: 0 },
    { key: 'ranks_2_3', index: 1 },
    { key: 'ranks_4_5', index: 2 },
    { key: 'ranks_6_10', index: 3 },
    { key: 'ranks_11_plus', index: 4 },
  ];
  const headers = [
    'row_type',
    'provider',
    'source_domain',
    'topic',
    'intent',
    'unlabeled',
    'model',
    'surface',
    'locale',
    'prompt_groups_with_source',
    'captures_with_source',
    'sampled_timestamps_with_source',
    'prompt_groups_starting_with_source',
    'prompt_groups_ending_with_source',
    'ordered_transitions_with_source_presence',
    'source_present_at_previous_timestamp',
    'source_present_at_both_timestamps',
    'source_absent_at_next_timestamp',
    'source_transitions_observed_at_next_timestamp',
    'source_next_timestamp_unobserved_due_to_truncation',
    'source_first_appeared_at_next_timestamp',
    'source_presence_at_previous_timestamp_unobserved_due_to_truncation',
    'next_timestamp_retention_percent',
    'mean_days_until_next_sample_when_previously_cited',
    'longest_consecutive_sampled_timestamps_with_source',
    'first_observed_citation_at',
    'last_observed_citation_at',
    'source_persistence_profiles_available',
    'source_persistence_profiles_emitted',
    'source_persistence_working_profile_cap',
    'source_persistence_timestamp_check_budget',
    'source_persistence_timestamp_checks_performed',
    'source_persistence_bootstrap_update_budget',
    'source_persistence_bootstrap_updates_performed',
    'source_persistence_bootstrap_work_truncated',
    'source_persistence_output_profile_cap',
    'source_persistence_work_truncated',
    'source_persistence_profiles_truncated',
    'interpretation_note',
    'prompt_groups_with_source_present_transitions',
    'equal_prompt_mean_next_timestamp_retention_percent',
    'equal_prompt_mean_next_timestamp_retention_ci95_lower_percent',
    'equal_prompt_mean_next_timestamp_retention_ci95_upper_percent',
    'retention_bootstrap_status',
    ...intervalColumns.flatMap(({ key }) => [
      `next_timestamp_${key}_transitions_at_risk`,
      `next_timestamp_${key}_transitions_unobserved_due_to_truncation`,
      `next_timestamp_${key}_retained`,
      `next_timestamp_${key}_retention_percent`,
      `next_timestamp_${key}_prompt_groups_at_risk`,
      `next_timestamp_${key}_equal_prompt_mean_retention_percent`,
      `next_timestamp_${key}_equal_prompt_mean_retention_ci95_lower_percent`,
      `next_timestamp_${key}_equal_prompt_mean_retention_ci95_upper_percent`,
      `next_timestamp_${key}_retention_bootstrap_status`,
    ]),
    ...rankColumns.flatMap(({ key }) => [
      `next_timestamp_${key}_transitions_at_risk`,
      `next_timestamp_${key}_transitions_unobserved_due_to_truncation`,
      `next_timestamp_${key}_prompt_groups_at_risk`,
      `next_timestamp_${key}_retained`,
      `next_timestamp_${key}_retention_percent`,
    ]),
  ];
  const summary: Record<string, unknown> = {
    row_type: 'summary',
    source_persistence_profiles_available:
      report.sourcePersistenceProfilesAvailable ?? profiles.length,
    source_persistence_profiles_emitted: profiles.length,
    source_persistence_working_profile_cap: report.sourcePersistenceWorkingProfileCap ?? '',
    source_persistence_timestamp_check_budget: report.sourcePersistenceTimestampCheckBudget ?? '',
    source_persistence_timestamp_checks_performed:
      report.sourcePersistenceTimestampChecksPerformed ?? '',
    source_persistence_bootstrap_update_budget: report.sourcePersistenceBootstrapUpdateBudget ?? '',
    source_persistence_bootstrap_updates_performed:
      report.sourcePersistenceBootstrapUpdatesPerformed ?? '',
    source_persistence_bootstrap_work_truncated:
      report.sourcePersistenceBootstrapWorkTruncated ?? false,
    source_persistence_output_profile_cap: report.sourcePersistenceOutputProfileCap ?? '',
    source_persistence_work_truncated: report.sourcePersistenceWorkTruncated ?? false,
    source_persistence_profiles_truncated: report.sourcePersistenceProfilesTruncated ?? false,
    interpretation_note: note,
  };
  const rows: Array<Record<string, unknown>> = [
    summary,
    ...profiles.map((item) => ({
      row_type: 'source-persistence',
      provider: item.provider,
      source_domain: item.sourceDomain,
      topic: item.topic,
      intent: item.intent,
      unlabeled: item.unlabeled,
      model: item.model,
      surface: item.surface,
      locale: item.locale,
      prompt_groups_with_source: item.promptGroupsWithSource,
      captures_with_source: item.capturesWithSource,
      sampled_timestamps_with_source: item.sampledTimestampsWithSource,
      prompt_groups_starting_with_source: item.promptGroupsStartingWithSource,
      prompt_groups_ending_with_source: item.promptGroupsEndingWithSource,
      ordered_transitions_with_source_presence: item.orderedTransitionsWithSourcePresence,
      source_present_at_previous_timestamp: item.sourcePresentAtPreviousTimestamp,
      source_present_at_both_timestamps: item.sourcePresentAtBothTimestamps,
      source_absent_at_next_timestamp: item.sourceAbsentAtNextTimestamp,
      source_transitions_observed_at_next_timestamp:
        item.sourceTransitionsObservedAtNextTimestamp ?? '',
      source_next_timestamp_unobserved_due_to_truncation:
        item.sourceNextTimestampUnobservedDueToTruncation ?? '',
      source_first_appeared_at_next_timestamp: item.sourceFirstAppearedAtNextTimestamp,
      source_presence_at_previous_timestamp_unobserved_due_to_truncation:
        item.sourcePresenceAtPreviousTimestampUnobservedDueToTruncation ?? '',
      next_timestamp_retention_percent: item.nextTimestampRetentionPercent,
      mean_days_until_next_sample_when_previously_cited:
        item.meanDaysUntilNextSampleWhenPreviouslyCited,
      longest_consecutive_sampled_timestamps_with_source:
        item.longestConsecutiveSampledTimestampsWithSource,
      first_observed_citation_at: item.firstObservedCitationAt,
      last_observed_citation_at: item.lastObservedCitationAt,
      prompt_groups_with_source_present_transitions:
        item.promptGroupsWithSourcePresentTransitions ?? '',
      equal_prompt_mean_next_timestamp_retention_percent:
        item.equalPromptMeanNextTimestampRetentionPercent ?? '',
      equal_prompt_mean_next_timestamp_retention_ci95_lower_percent:
        item.equalPromptMeanNextTimestampRetentionConfidenceInterval95?.lower ?? '',
      equal_prompt_mean_next_timestamp_retention_ci95_upper_percent:
        item.equalPromptMeanNextTimestampRetentionConfidenceInterval95?.upper ?? '',
      retention_bootstrap_status: item.retentionBootstrapStatus ?? '',
      source_persistence_profiles_truncated: report.sourcePersistenceProfilesTruncated ?? false,
      interpretation_note: note,
      ...Object.fromEntries(
        intervalColumns.flatMap(({ key, index }) => {
          const band = item.retentionByFollowUpInterval?.[index];
          return [
            [`next_timestamp_${key}_transitions_at_risk`, band?.transitionsAtRisk ?? ''],
            [
              `next_timestamp_${key}_transitions_unobserved_due_to_truncation`,
              band?.transitionsUnobservedDueToTruncation ?? '',
            ],
            [`next_timestamp_${key}_retained`, band?.retainedAtNextTimestamp ?? ''],
            [`next_timestamp_${key}_retention_percent`, band?.retentionPercent ?? ''],
            [`next_timestamp_${key}_prompt_groups_at_risk`, band?.promptGroupsAtRisk ?? ''],
            [
              `next_timestamp_${key}_equal_prompt_mean_retention_percent`,
              band?.equalPromptMeanRetentionPercent ?? '',
            ],
            [
              `next_timestamp_${key}_equal_prompt_mean_retention_ci95_lower_percent`,
              band?.equalPromptMeanRetentionConfidenceInterval95?.lower ?? '',
            ],
            [
              `next_timestamp_${key}_equal_prompt_mean_retention_ci95_upper_percent`,
              band?.equalPromptMeanRetentionConfidenceInterval95?.upper ?? '',
            ],
            [`next_timestamp_${key}_retention_bootstrap_status`, band?.bootstrapStatus ?? ''],
          ];
        })
      ),
      ...Object.fromEntries(
        rankColumns.flatMap(({ key, index }) => {
          const band = item.retentionByPreviousCitationRank?.[index];
          return [
            [`next_timestamp_${key}_transitions_at_risk`, band?.transitionsAtRisk ?? ''],
            [
              `next_timestamp_${key}_transitions_unobserved_due_to_truncation`,
              band?.transitionsUnobservedDueToTruncation ?? '',
            ],
            [`next_timestamp_${key}_prompt_groups_at_risk`, band?.promptGroupsAtRisk ?? ''],
            [`next_timestamp_${key}_retained`, band?.retainedAtNextTimestamp ?? ''],
            [`next_timestamp_${key}_retention_percent`, band?.retentionPercent ?? ''],
          ];
        })
      ),
    })),
  ];
  return `${[headers, ...rows.map((row) => headers.map((header) => row[header] ?? ''))].map((row) => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

/** Export exact-prompt citation-URL retention to the next distinct sampled timestamp. */
export function renderAiAnswerCitationUrlPersistenceCsv(
  report: AiAnswerCitationObservationReport
): string {
  const profiles = report.citationUrlPersistenceProfiles;
  if (!profiles)
    throw new Error(
      'This report does not contain citation-URL persistence detail; reanalyze with URL persistence enabled.'
    );
  const note =
    'Within each provider, exact normalized prompt, and recorded context group, simultaneous captures are pooled and a normalized citation URL is present when any capture lists it. Retention is calculated only when the next timestamp is observable; if the URL is absent and every simultaneous citation list is incomplete, the transition is unknown and excluded from the denominator. Set citationListComplete=false for incomplete observations; a 50-URL list defaults to incomplete unless explicitly marked true. First appearance after prior absence is counted only when a previous list confirms absence; prior-state unknown counts are exported separately. This is sampled page recurrence, not continuous-time survival or a quality measure.';
  const headers = [
    'row_type',
    'provider',
    'citation_url',
    'topic',
    'intent',
    'unlabeled',
    'model',
    'surface',
    'locale',
    'prompt_groups_with_url',
    'captures_with_url',
    'sampled_timestamps_with_url',
    'prompt_groups_starting_with_url',
    'prompt_groups_ending_with_url',
    'ordered_transitions_with_url_presence',
    'url_present_at_previous_timestamp',
    'url_present_at_both_timestamps',
    'url_absent_at_next_timestamp',
    'url_transitions_observed_at_next_timestamp',
    'url_next_timestamp_unobserved_due_to_truncation',
    'url_first_appeared_at_next_timestamp',
    'url_presence_at_previous_timestamp_unobserved_due_to_truncation',
    'next_timestamp_retention_percent',
    'first_observed_citation_at',
    'last_observed_citation_at',
    'citation_url_persistence_profiles_available',
    'citation_url_persistence_profiles_emitted',
    'citation_url_persistence_working_profile_cap',
    'citation_url_persistence_timestamp_check_budget',
    'citation_url_persistence_timestamp_checks_performed',
    'citation_url_persistence_output_profile_cap',
    'citation_url_persistence_work_truncated',
    'citation_url_persistence_profiles_truncated',
    'interpretation_note',
  ];
  const summary: Record<string, unknown> = {
    row_type: 'summary',
    citation_url_persistence_profiles_available:
      report.citationUrlPersistenceProfilesAvailable ?? profiles.length,
    citation_url_persistence_profiles_emitted: profiles.length,
    citation_url_persistence_working_profile_cap:
      report.citationUrlPersistenceWorkingProfileCap ?? '',
    citation_url_persistence_timestamp_check_budget:
      report.citationUrlPersistenceTimestampCheckBudget ?? '',
    citation_url_persistence_timestamp_checks_performed:
      report.citationUrlPersistenceTimestampChecksPerformed ?? '',
    citation_url_persistence_output_profile_cap:
      report.citationUrlPersistenceOutputProfileCap ?? '',
    citation_url_persistence_work_truncated: report.citationUrlPersistenceWorkTruncated ?? false,
    citation_url_persistence_profiles_truncated:
      report.citationUrlPersistenceProfilesTruncated ?? false,
    interpretation_note: note,
  };
  const rows: Array<Record<string, unknown>> = [
    summary,
    ...profiles.map((item) => ({
      row_type: 'citation-url-persistence',
      provider: item.provider,
      citation_url: item.citationUrl,
      topic: item.topic,
      intent: item.intent,
      unlabeled: item.unlabeled,
      model: item.model,
      surface: item.surface,
      locale: item.locale,
      prompt_groups_with_url: item.promptGroupsWithUrl,
      captures_with_url: item.capturesWithUrl,
      sampled_timestamps_with_url: item.sampledTimestampsWithUrl,
      prompt_groups_starting_with_url: item.promptGroupsStartingWithUrl,
      prompt_groups_ending_with_url: item.promptGroupsEndingWithUrl,
      ordered_transitions_with_url_presence: item.orderedTransitionsWithUrlPresence,
      url_present_at_previous_timestamp: item.urlPresentAtPreviousTimestamp,
      url_present_at_both_timestamps: item.urlPresentAtBothTimestamps,
      url_absent_at_next_timestamp: item.urlAbsentAtNextTimestamp,
      url_transitions_observed_at_next_timestamp: item.urlTransitionsObservedAtNextTimestamp ?? '',
      url_next_timestamp_unobserved_due_to_truncation:
        item.urlNextTimestampUnobservedDueToTruncation ?? '',
      url_first_appeared_at_next_timestamp: item.urlFirstAppearedAtNextTimestamp,
      url_presence_at_previous_timestamp_unobserved_due_to_truncation:
        item.urlPresenceAtPreviousTimestampUnobservedDueToTruncation ?? '',
      next_timestamp_retention_percent: item.nextTimestampRetentionPercent,
      first_observed_citation_at: item.firstObservedCitationAt,
      last_observed_citation_at: item.lastObservedCitationAt,
      citation_url_persistence_profiles_truncated:
        report.citationUrlPersistenceProfilesTruncated ?? false,
      interpretation_note: note,
    })),
  ];
  return `${[headers, ...rows.map((row) => headers.map((header) => row[header] ?? ''))].map((row) => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

