/** Compare owned-citation list prominence within exact entity-mention samples. */
export function renderAiAnswerCitationEntityCitationPositionComparisonCsv(
  report: AiAnswerCitationObservationReport
): string {
  const entities = report.periodComparison?.entityMentionComparison?.entities;
  if (!entities)
    throw new Error(
      'Entity citation-position comparison requires baseline/current answer observations with the same configured entity names and aliases.'
    );
  if (
    !entities.some(
      (entity) =>
        entity.baseline?.ownedCitationPositionWhenMentioned !== undefined &&
        entity.current?.ownedCitationPositionWhenMentioned !== undefined
    )
  ) {
    throw new Error(
      'Entity citation-position comparison requires owned-domain configuration and owned citation rank profiles in both periods.'
    );
  }
  const headers = [
    'entity',
    'aliases',
    'scope',
    'provider',
    'month',
    'topic',
    'intent',
    'unlabeled',
    'sample_state',
    'monthly_profile_comparison_truncated',
    'baseline_observations',
    'current_observations',
    'baseline_unique_prompts',
    'current_unique_prompts',
    'baseline_answer_text_observations',
    'current_answer_text_observations',
    'baseline_observations_mentioning_entity',
    'current_observations_mentioning_entity',
    'baseline_observations_without_entity_mention',
    'current_observations_without_entity_mention',
    'baseline_owned_events_when_mentioned',
    'current_owned_events_when_mentioned',
    'baseline_owned_first_position_events_when_mentioned',
    'current_owned_first_position_events_when_mentioned',
    'baseline_owned_first_position_share_when_mentioned_percent',
    'current_owned_first_position_share_when_mentioned_percent',
    'owned_first_position_share_when_mentioned_change_percentage_points',
    'baseline_owned_top_three_events_when_mentioned',
    'current_owned_top_three_events_when_mentioned',
    'baseline_owned_top_three_share_when_mentioned_percent',
    'current_owned_top_three_share_when_mentioned_percent',
    'owned_top_three_share_when_mentioned_change_percentage_points',
    'baseline_owned_events_when_not_mentioned',
    'current_owned_events_when_not_mentioned',
    'baseline_owned_first_position_events_when_not_mentioned',
    'current_owned_first_position_events_when_not_mentioned',
    'baseline_owned_first_position_share_when_not_mentioned_percent',
    'current_owned_first_position_share_when_not_mentioned_percent',
    'owned_first_position_share_when_not_mentioned_change_percentage_points',
    'baseline_owned_top_three_events_when_not_mentioned',
    'current_owned_top_three_events_when_not_mentioned',
    'baseline_owned_top_three_share_when_not_mentioned_percent',
    'current_owned_top_three_share_when_not_mentioned_percent',
    'owned_top_three_share_when_not_mentioned_change_percentage_points',
    'interpretation_note',
  ];
  const summaryRows = entities.flatMap((entity) =>
    [
      { scope: 'overall', provider: undefined, comparison: entity },
      ...entity.providerProfiles.map((comparison) => ({
        scope: 'provider',
        provider: comparison.provider,
        comparison,
      })),
    ].map(({ scope, provider, comparison }) => {
      const baseline = comparison.baseline;
      const current = comparison.current;
      const state =
        baseline && current
          ? 'matched'
          : baseline
            ? 'baseline-only'
            : current
              ? 'current-only'
              : 'unavailable';
      return [
        entity.entity,
        entity.aliases.join('; '),
        scope,
        provider,
        undefined,
        undefined,
        undefined,
        undefined,
        state,
        entity.monthlyProfilesTruncated,
        baseline
          ? baseline.observationsWithAnswerText + baseline.observationsWithoutAnswerText
          : undefined,
        current
          ? current.observationsWithAnswerText + current.observationsWithoutAnswerText
          : undefined,
        undefined,
        undefined,
        baseline?.observationsWithAnswerText,
        current?.observationsWithAnswerText,
        baseline?.observationsMentioningEntity,
        current?.observationsMentioningEntity,
        baseline?.observationsWithoutEntityMention,
        current?.observationsWithoutEntityMention,
        baseline?.ownedCitationPositionWhenMentioned?.citationEvents,
        current?.ownedCitationPositionWhenMentioned?.citationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.firstPositionCitationEvents,
        current?.ownedCitationPositionWhenMentioned?.firstPositionCitationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.firstPositionCitationSharePercent,
        current?.ownedCitationPositionWhenMentioned?.firstPositionCitationSharePercent,
        comparison.ownedFirstPositionShareWhenMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenMentioned?.topThreeCitationEvents,
        current?.ownedCitationPositionWhenMentioned?.topThreeCitationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.topThreeCitationSharePercent,
        current?.ownedCitationPositionWhenMentioned?.topThreeCitationSharePercent,
        comparison.ownedTopThreeShareWhenMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenNotMentioned?.citationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.citationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationSharePercent,
        current?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationSharePercent,
        comparison.ownedFirstPositionShareWhenNotMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenNotMentioned?.topThreeCitationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.topThreeCitationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.topThreeCitationSharePercent,
        current?.ownedCitationPositionWhenNotMentioned?.topThreeCitationSharePercent,
        comparison.ownedTopThreeShareWhenNotMentionedChangePercentagePoints,
        'Owned-rank shares use the supplied order of citations that match configured owned domains and are conditional on entity mention status. Event counts are included as context; periods with no owned events have blank shares. This describes the retained manually sampled answers, not source quality or causation.',
      ];
    })
  );
  const monthlyRows = entities.flatMap((entity) =>
    entity.monthlyProfiles.map((comparison) => {
      const baseline = comparison.baseline;
      const current = comparison.current;
      return [
        entity.entity,
        entity.aliases.join('; '),
        'month-provider-cohort',
        comparison.provider,
        comparison.month,
        comparison.topic,
        comparison.intent,
        comparison.unlabeled,
        comparison.sampleState,
        entity.monthlyProfilesTruncated,
        comparison.baselineObservations,
        comparison.currentObservations,
        comparison.baselineUniquePrompts,
        comparison.currentUniquePrompts,
        baseline?.observationsWithAnswerText,
        current?.observationsWithAnswerText,
        baseline?.observationsMentioningEntity,
        current?.observationsMentioningEntity,
        baseline?.observationsWithoutEntityMention,
        current?.observationsWithoutEntityMention,
        baseline?.ownedCitationPositionWhenMentioned?.citationEvents,
        current?.ownedCitationPositionWhenMentioned?.citationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.firstPositionCitationEvents,
        current?.ownedCitationPositionWhenMentioned?.firstPositionCitationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.firstPositionCitationSharePercent,
        current?.ownedCitationPositionWhenMentioned?.firstPositionCitationSharePercent,
        comparison.ownedFirstPositionShareWhenMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenMentioned?.topThreeCitationEvents,
        current?.ownedCitationPositionWhenMentioned?.topThreeCitationEvents,
        baseline?.ownedCitationPositionWhenMentioned?.topThreeCitationSharePercent,
        current?.ownedCitationPositionWhenMentioned?.topThreeCitationSharePercent,
        comparison.ownedTopThreeShareWhenMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenNotMentioned?.citationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.citationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationSharePercent,
        current?.ownedCitationPositionWhenNotMentioned?.firstPositionCitationSharePercent,
        comparison.ownedFirstPositionShareWhenNotMentionedChangePercentagePoints,
        baseline?.ownedCitationPositionWhenNotMentioned?.topThreeCitationEvents,
        current?.ownedCitationPositionWhenNotMentioned?.topThreeCitationEvents,
        baseline?.ownedCitationPositionWhenNotMentioned?.topThreeCitationSharePercent,
        current?.ownedCitationPositionWhenNotMentioned?.topThreeCitationSharePercent,
        comparison.ownedTopThreeShareWhenNotMentionedChangePercentagePoints,
        'Monthly period row joined on normalized entity, provider, month, topic, intent, and unlabeled state. One-sided rows report sample presence only; rate deltas are unavailable without both periods.',
      ];
    })
  );
  const rows = [...summaryRows, ...monthlyRows];
  return `${[headers, ...rows].map((row) => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

